window.getIcon = function(name, extraClass = '') {
  if (!window.GPO_ICONS || !window.GPO_ICONS[name]) return '';
  if (!extraClass) return window.GPO_ICONS[name];
  return window.GPO_ICONS[name].replace('class="gpo-icon"', 'class="gpo-icon ' + extraClass + '"');
};
